const text=($json.message.text||'').trim();
const cmd=(text.match(/#(pitch|proposal|contract|won|lost)/i)||[])[1]?.toLowerCase()||'skip';
if(cmd==='skip')return [];
return [{ json: { cmd, arg: text.replace(/#\w+/,'').trim(), chat: $json.message.chat.id } }];

// Chase engine ⑯: proposals/contracts still Draft/Sent after 2 & 5 days → chase list; Won → onboarding ping ⑰㉒㉓; ask referral ⑳
const td=new Date();
let out=[];
for(const it of items){const r=it.json;const age=Math.round((td-new Date(r.Date))/864e5);
if(['Draft','Sent'].includes(r.Status)&&[2,5].includes(age))out.push(`• ⏳ D+${age} chase: ${r.Cmd} for "${(r.Input||'').slice(0,40)}" — nudge the prospect`);
if(r.Status==='Won'&&age===0)out.push(`• 🏆 WON: "${(r.Input||'').slice(0,40)}" → send welcome pack, request accesses (Meta/GBP/site/GA4), book kickoff, POST to O3 /o-project-in`);
if(r.Status==='Won'&&age===14)out.push(`• 🤝 Referral ask: client from "${(r.Input||'').slice(0,30)}" — ask for 1 intro`);}
return [{ json: { text: out.length?'📜 SALES ENGINE TODAY:\n'+out.join('\n'):'✅ Nothing to chase.' } }];
